import java.sql.Connection; import java.sql.DriverManager; import java.sql.Statement; public class CleanDb { public static void main(String[] args) { try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost:5432/seal_hms", "postgres", "postgres"); Statement stmt = conn.createStatement()) { stmt.executeUpdate("TRUNCATE TABLE event CASCADE;"); System.out.println("Database hackathon data cleaned successfully!"); } catch (Exception e) { e.printStackTrace(); } } }
